let viewport = null, historyUI = null, projectLibraryUI = null, projectLibraryController = null, projectBackupUI = null, projectBackupTransport = null, namedProjectStore = null, projectConfirmation = null;
let comparing = false, painting = false, pointer = null, exportFormat = 'image/jpeg', exportPending = false;
let renderVersion = 0, pendingFrame = 0, draftTimer = 0, toastTimer = 0, hasSaved = true, thumbUrl = '';
let dbPromise = null, imageName = '', draftRecord = null, importVersion = 0, currentStroke = null;
