async function prepareNamedProject(input,kind,options){
 const token=beginSourceImport();if(window.PortraitUI)window.PortraitUI.cancelJob();cancelActivePointer();if(viewport)viewport.cancel(true);let next=null,rendered=null;
 try{
  let record=kind==='record'?input:null,blob=record?(record.version===1?record.blob:record.source&&record.source.blob):input;
  if(!blob||!Number.isSafeInteger(blob.size)||blob.size<=0||blob.size>40*1024*1024)throw Error('请选择有效且不超过 40 MiB 的原始照片');
  if(record)window.ProjectCore.restoreProject(record,{width:1,height:1});
  next=await decodeBlob(blob);if(token!==importVersion)throw Error('已有更新的照片请求，本次切换已取消');
  const dimensions={width:next.originalWidth||next.width,height:next.originalHeight||next.height};
  const project=record?window.ProjectCore.restoreProject(record,dimensions):window.ProjectCore.makeProject({blob,name:blob.name||'照片',mime:blob.type||'application/octet-stream',...dimensions,origin:'original'});
  if(project.source.width!==dimensions.width||project.source.height!==dimensions.height)throw Error('工程原图尺寸或方向不一致，未覆盖当前照片');
  // Pixel-dependent constraints also apply to history that is currently undone.
  // Layer collapse can hide previous versions: validate each prefix immediately
  // before a text/paint/image mutation, then the future chain and current state.
  const history=project.ops.concat(project.redo.slice().reverse()),lengths=new Set();
  if(project.redo.length)lengths.add(history.length);
  for(let i=1;i<history.length;i++)if(['text-overlay','paint-layer','image-overlay'].includes(history[i].type)&&history[i].action!=='add')lengths.add(i);
  lengths.delete(project.ops.length);
  for(const length of [...lengths].sort((a,b)=>a-b)){
   if(token!==importVersion||(options&&options.shouldCancel&&options.shouldCancel()))throw Error('工程恢复已取消，当前照片仍保留');
   const replay=renderPipeline(PREVIEW_SIDE,history.slice(0,length),next,true);
   if(replay!==next){replay.width=1;replay.height=1;}
   await new Promise(resolve=>setTimeout(resolve,0));
  }
  if(token!==importVersion||(options&&options.shouldCancel&&options.shouldCancel()))throw Error('工程恢复已取消，当前照片仍保留');
  rendered=renderPipeline(PREVIEW_SIDE,project.ops,next,true);
  return{project,source:next,rendered,token};
 }catch(error){if(next&&next!==source){next.width=1;next.height=1;}if(rendered&&rendered!==committed){rendered.width=1;rendered.height=1;}finishSourceImport(token);throw error;}
}
